export type PlatformRole =
  | 'org_admin'
  | 'project_admin'
  | 'operator'
  | 'space_user';

export type AppModuleId =
  | 'home'
  | 'analysis'
  | 'alarms'
  | 'scenes'
  | 'settings'
  | 'deployment'
  | 'account';

export type OverrideTargetModule = 'deployment' | 'settings';
export type OverrideDurationHours = 2 | 8 | 24;

export const ROLE_LABELS: Record<PlatformRole, string> = {
  org_admin: '机构管理员',
  project_admin: '项目管理员',
  operator: '运营人员',
  space_user: '空间用户',
};

export const ROLE_DESCRIPTIONS: Record<PlatformRole, string> = {
  org_admin: '机构全范围管理、成员与角色治理、临时提权审批、审计日志只读核查',
  project_admin: '授权项目全范围管理、应用设置与系统部署、项目内成员管理与限时提权审批',
  operator: '授权范围日常值守、设备控制、告警与工单处置；设置与部署默认只读，可经限时提权修改',
  space_user: '仅访问授权楼层与功能区，进行日常灯光与空调控制',
};

/** IEC 62443-3-3 SR 2.1 RE 3 主管覆盖 / 限时提权记录 */
export interface TemporaryOverride {
  id: string;
  targetUserId: string;
  targetUserName: string;
  module: OverrideTargetModule;
  durationHours: OverrideDurationHours;
  grantedAt: string;
  expiresAt: string;
  approvedBy: string;
  reason: string;
  status: 'active' | 'revoked' | 'expired';
  revokedAt?: string | null;
  revokedBy?: string | null;
}

export interface GrantOverrideRequest {
  targetUserId: string;
  module: OverrideTargetModule;
  durationHours: OverrideDurationHours;
  reason: string;
}

export interface LoginRequest {
  account: string;
  password: string;
}

/** 服务端下发的真实资源授权范围（前端不得伪造，接口必须二次校验，写权限绝不隐含在读权限中） */
export interface AccessScope {
  allowedProjectIds: string[];
  allowedBuildingIds: string[];
  allowedFloorIds: string[];
  allowedZoneIds?: string[];
  visibleModules: AppModuleId[];
  canControlDevices: boolean;
  canManageAlarms: boolean;
  canEditScenes: boolean;
  canEditSettings: boolean;
  canEditDeployment: boolean;
  canManageMembers: boolean;
  canGrantOverride: boolean;
  canViewAuditLogs: boolean;
  activeOverrides: TemporaryOverride[];
}

export interface UserSession {
  userId: string;
  displayName: string;
  role: PlatformRole;
  roleLabel: string;
  scope: AccessScope;
  authMode: 'demo' | 'live';
}
